#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=13

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
ENV_FILE="$REPO_ROOT/.env"
WORK="$REPO_ROOT/.wizard"
mkdir -p "$WORK"

TS_CLI="/Applications/Tailscale.app/Contents/MacOS/Tailscale"
COMPOSE=(docker compose -f docker-compose.yml -f docker-compose.local.yml)

# port_free PORT — usable for hawk-mod. Nothing listening counts as free, and
# so does hawk-mod's own container: a re-run should reuse its port, not be told
# to pick a new one and start a second copy.
port_free() {
  lsof -nP -iTCP:"$1" -sTCP:LISTEN >/dev/null 2>&1 || return 0
  [[ "$(holder_of "$1")" == "hawk-mod" ]]
}

# holder_of PORT — the docker container publishing it, if any.
holder_of() {
  docker ps --format '{{.Names}} {{.Ports}}' 2>/dev/null \
    | grep ":$1->" | awk '{print $1}' | head -1
}

# whats_on PORT — best-effort description of the squatter, for the error.
whats_on() {
  local c
  c=$(holder_of "$1")
  [[ -n "$c" ]] && printf 'docker container "%s"' "$c" && return
  lsof -nP -iTCP:"$1" -sTCP:LISTEN 2>/dev/null | awk 'NR==2{print $1}'
}

# start_funnel PORT — returns 0 on success, 2 if the tailnet needs Funnel
# enabled first (the CLI blocks polling in that case, so it is run in the
# background and watched rather than waited on).
start_funnel() {
  local port="$1" pid waited=0
  : > "$WORK/funnel.log"
  "$TS_CLI" funnel --bg "$port" >"$WORK/funnel.log" 2>&1 &
  pid=$!
  while kill -0 "$pid" 2>/dev/null && (( waited < 20 )); do
    if grep -q "login.tailscale.com/f/funnel" "$WORK/funnel.log" 2>/dev/null; then
      kill "$pid" 2>/dev/null || true
      return 2
    fi
    sleep 1
    waited=$((waited + 1))
  done
  if kill -0 "$pid" 2>/dev/null; then
    kill "$pid" 2>/dev/null || true
    return 3
  fi
  wait "$pid" 2>/dev/null
}

# cert_ok — Funnel serves nothing without a TLS certificate, and issuance can
# fail server-side. Provisioning it here turns a stage-10 mystery into a stage-3
# error message. Writes into $WORK so no cert files land in the repo.
cert_ok() {
  local host="$1"
  ( cd "$WORK" && "$TS_CLI" cert --cert-file tls.crt --key-file tls.key "$host" ) \
    >"$WORK/cert.log" 2>&1
}

# start_cloudflared PORT — quick tunnel, no account and no certificate of your
# own (Cloudflare's wildcard covers it). Prints nothing of yours to public
# certificate logs. The URL changes every restart.
start_cloudflared() {
  local port="$1" waited=0
  # A previous run may have left one up. Two tunnels means two URLs, and the
  # Slack app can only point at one of them.
  if [[ -f "$WORK/cloudflared.pid" ]] && kill -0 "$(cat "$WORK/cloudflared.pid")" 2>/dev/null; then
    CF_URL=$(grep -o 'https://[a-z0-9-]*\.trycloudflare\.com' "$WORK/cloudflared.log" | head -1) || true
    if [[ -n "${CF_URL:-}" ]]; then
      note "Reusing the tunnel already running (pid $(cat "$WORK/cloudflared.pid"))."
      return 0
    fi
  fi
  : > "$WORK/cloudflared.log"
  nohup cloudflared tunnel --no-autoupdate --url "http://localhost:${port}" \
    >"$WORK/cloudflared.log" 2>&1 &
  echo $! > "$WORK/cloudflared.pid"
  while (( waited < 30 )); do
    CF_URL=$(grep -o 'https://[a-z0-9-]*\.trycloudflare\.com' "$WORK/cloudflared.log" \
      | head -1) || true
    [[ -n "${CF_URL:-}" ]] && return 0
    sleep 1
    waited=$((waited + 1))
  done
  return 1
}

# clip FILE — put a file on the clipboard so it can be pasted into a browser.
clip() {
  if command -v pbcopy >/dev/null 2>&1; then
    pbcopy < "$1" && printf '  %s✓%s copied to your clipboard\n' "$GREEN" "$RESET"
  else
    note "copy it from: $1"
  fi
}

# hm CMD... — the CLI inside the running container, which holds the .env.
hm() { "${COMPOSE[@]}" exec -T hawk-mod node dist/src/cli/index.js "$@"; }

# key_email — the service account the key in .env belongs to, and nothing
# else from it: the rest of that JSON is the private key.
key_email() {
  printf '%s' "$1" | python3 -c '
import base64, json, sys
try:
    print(json.loads(base64.b64decode(sys.stdin.read())).get("client_email", ""))
except Exception:
    pass
'
}

# write_test_sheet — one TSV per tab of a small, fake lifecycle sheet, in
# $WORK/test-sheet. The tabs and headers come from SHEET_TABS in the built
# image, so the test sheet has exactly the columns hawk-mod reads and cannot
# drift from them; a header the rows below do not know stays blank.
#
# The people are fake and the addresses are accounts the person running this
# controls. P0001–P0003 are avoided: the parser ignores them as the real
# sheet's sample rows.
write_test_sheet() {
  mkdir -p "$WORK/test-sheet"
  docker run --rm \
    -e MENTOR_EMAIL="$MENTOR_EMAIL" -e STUDENT_EMAIL="$STUDENT_EMAIL" \
    -e NEXT_AUG1="$NEXT_AUG1" -e IN_TWO_YEARS="$IN_TWO_YEARS" \
    -e STUDENT_CONSENT="$STUDENT_CONSENT" \
    hawk-mod:local node --input-type=module -e '
const { SHEET_TABS } = await import("./dist/src/domain/lifecycle/schema.js");
const e = process.env;
const rows = {
  People: [
    { "Person ID": "P0101", "Legal First Name": "Test", "Legal Last Name": "Mentor",
      "Active/Inactive": "Active" },
    { "Person ID": "P0102", "Legal First Name": "Test", "Legal Last Name": "Student",
      "Active/Inactive": "Active" },
  ],
  People_Roles: [
    { "Person ID": "P0101", Role: "Mentor" },
    { "Person ID": "P0102", Role: "Student" },
  ],
  Mentor_Details: [
    { "Person ID": "P0101", "RHR Email": e.MENTOR_EMAIL,
      "YPT Expiry": e.NEXT_AUG1, "Background Screening Expiry": e.IN_TWO_YEARS,
      "CORI Expiry": e.IN_TWO_YEARS, "Consent & Release Expiry": e.NEXT_AUG1,
      "Data Privacy Expiry": e.NEXT_AUG1, "Mentor Lead (Y/N)": "N", "RA (Y/N)": "N" },
  ],
  Student_Details: [
    { "Person ID": "P0102", "School Email": e.STUDENT_EMAIL,
      "Student Lead (Y/N)": "N", "Slack Consent Expiry": e.STUDENT_CONSENT },
  ],
};
const out = {};
for (const [tab, headers] of Object.entries(SHEET_TABS)) {
  const line = (r) => headers.map((h) => r[h] ?? "").join("\t");
  out[tab] = [headers.join("\t"), ...(rows[tab] ?? []).map(line)].join("\n") + "\n";
}
console.log(JSON.stringify(out));
' > "$WORK/test-sheet.json"
  SHEET_TAB_LIST=()
  while IFS= read -r tab; do SHEET_TAB_LIST+=("$tab"); done < <(
    python3 - "$WORK/test-sheet.json" "$WORK/test-sheet" <<'PY'
import json, sys
tabs = json.load(open(sys.argv[1]))
for tab, text in tabs.items():
    open(f"{sys.argv[2]}/{tab}.tsv", "w").write(text)
    print(tab)
PY
  )
}

banner "hawk-mod — local test setup"

# ──────────────────────────────────────────────────────────────────────────
stage "Scope — what this will and won't record"
say "Roles come from the lifecycle Google Sheet. That is what bounds this test:"
say ""
say "  ${BOLD}hawk-mod records a DM only when it contains both an adult and"
say "  a student.${RESET} Student-only and adult-only conversations are never"
say "  recorded, and students cannot enrol."
say ""
warn "Do NOT point this at the real lifecycle sheet."
say "The roster is everyone that sheet declares. Combined with you enrolling,"
say "that means your DMs with real students start being recorded on this"
say "laptop — and the sheet itself is every minor's name and school email."
say ""
say "For the test you'll make a small sheet of your own with two fake people"
say "on it, whose addresses are accounts you control, and a Google service"
say "account that can read that sheet and nothing else."
say ""
say "You'll need a second Slack account to play the student. A +alias works:"
note "    you+student@gmail.com"
if ! confirm "Understood — a test sheet, not the real one?"; then
  say "Stopping. Nothing has been changed."
  exit 0
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Preflight — Docker"
say "Checking Docker and building the image."
if ! docker info >/dev/null 2>&1; then
  warn "Docker isn't running. Start Docker Desktop, then re-run this script."
  exit 1
fi
docker network inspect edge >/dev/null 2>&1 || docker network create edge >/dev/null
say "Docker network 'edge' ready."
LOCAL_PORT="$(_existing LOCAL_PORT || echo 3000)"
if ! port_free "$LOCAL_PORT"; then
  warn "Port $LOCAL_PORT is already taken by $(whats_on "$LOCAL_PORT")."
  say "That matters more than it looks: the Funnel forwards the public"
  say "internet to whatever answers on this port. Pick one that is free."
  SUGGESTED=3001
  for candidate in 3001 3002 3003 3010 3100; do
    if port_free "$candidate"; then SUGGESTED="$candidate"; break; fi
  done
  note "$SUGGESTED is free."
  ask LOCAL_PORT "Host port for hawk-mod:"
  LOCAL_PORT="${LOCAL_PORT:-$SUGGESTED}"
  if ! port_free "$LOCAL_PORT"; then
    warn "Port $LOCAL_PORT is taken too. Free one up and re-run."
    exit 1
  fi
elif [[ "$(holder_of "$LOCAL_PORT")" == "hawk-mod" ]]; then
  say "Port $LOCAL_PORT is hawk-mod's own container from an earlier run; reusing it."
fi
write_env LOCAL_PORT "$LOCAL_PORT"
say "hawk-mod will use host port $LOCAL_PORT (the container still listens on 3000)."
say ""
say "Building the image (a minute or two the first time)…"
docker build -t hawk-mod:local . >/dev/null
printf '  %s✓%s image hawk-mod:local built\n' "$GREEN" "$RESET"

# ──────────────────────────────────────────────────────────────────────────
stage "Public URL — Tailscale Funnel"
say "Slack has to reach this machine over public HTTPS, for both event"
say "delivery and the OAuth redirect. Tailscale Funnel gives a stable"
say "hostname with a real certificate."
say ""
# Read Self.DNSName specifically — `status --json` also lists every peer, so a
# first-match grep can hand back a different machine on the tailnet.
FUNNEL_HOST="$("$TS_CLI" status --json 2>/dev/null | python3 -c '
import json, sys
try:
    print(json.load(sys.stdin).get("Self", {}).get("DNSName", "").rstrip("."))
except Exception:
    pass
' 2>/dev/null)"
if [[ -z "$FUNNEL_HOST" ]]; then
  warn "Couldn't read this machine's Tailscale name. Is Tailscale signed in?"
  exit 1
fi
PUBLIC_URL="https://${FUNNEL_HOST}"
say "This machine is ${BOLD}${FUNNEL_HOST}${RESET}"
say ""
warn "Read this before agreeing — Funnel is genuinely public."
say "It exposes ONLY port ${LOCAL_PORT} of this Mac (nothing else on the"
say "machine), but"
say "it exposes it to the whole internet. Do not treat the hostname as a"
say "secret: Tailscale gets a Let's Encrypt cert for it, and every issued cert"
say "is published to public Certificate Transparency logs."
say ""
say "What is actually listening on ${LOCAL_PORT}:"
note "  /slack/events         rejects anything without a valid Slack signature"
note "  /slack/oauth_redirect  rejects callbacks without the signed state param"
note "  /slack/install         redirects to Slack's own consent screen"
note "  /health                returns status + how many adults are enrolled"
say ""
say "No message content, no database, and no admin surface is served over HTTP."
say "The safety here is that every endpoint is authenticated — not that the"
say "URL is hard to guess."
say ""
say "It will forward to ${BOLD}localhost:${LOCAL_PORT}${RESET}, which is hawk-mod and"
say "nothing else — the port was checked in the previous stage."
say ""
warn "Funnel persists across restarts. Turn it off when you're done:"
note "    $TS_CLI funnel --https=443 off"
if ! confirm "Start the Funnel now?"; then
  say "Stopping — hawk-mod can't be tested without a public URL."
  exit 0
fi

rc=0; start_funnel "$LOCAL_PORT" || rc=$?
if (( rc == 2 )); then
  say ""
  warn "Funnel isn't enabled for this tailnet yet."
  ENABLE_URL="$(grep -o 'https://login.tailscale.com/f/funnel[^[:space:]]*' \
    "$WORK/funnel.log" | head -1)"
  step "Approve it here, then come back:"
  open_url "$ENABLE_URL"
  pause "Press Enter once you've approved it."
  rc=0; start_funnel "$LOCAL_PORT" || rc=$?
fi
if (( rc != 0 )); then
  warn "Funnel didn't start. What it said:"
  sed 's/^/    /' "$WORK/funnel.log"
  say ""
  step "If it mentions HTTPS certificates, enable them here and re-run:"
  open_url "https://login.tailscale.com/admin/dns"
  exit 1
fi
printf '  %s✓%s funnel on: %s → localhost:%s\n' \
  "$GREEN" "$RESET" "$PUBLIC_URL" "$LOCAL_PORT"

# Funnel being "on" is not the same as it working: without a TLS certificate
# every request dies in the handshake, and issuance can fail on Tailscale's
# side. Check now rather than three stages later.
say "Checking a TLS certificate can actually be issued…"
if cert_ok "$FUNNEL_HOST"; then
  printf '  %s✓%s certificate in place\n' "$GREEN" "$RESET"
else
  warn "Tailscale could not issue a certificate:"
  sed 's/^/    /' "$WORK/cert.log" | head -4
  say ""
  say "Without it, Funnel answers every request with a TLS error. If that says"
  say "\"failed to create DNS record\", it is Tailscale's control plane, not"
  say "anything you configured."
  say ""
  step "Worth one try: toggle HTTPS Certificates off and on, then re-run."
  open_url "https://login.tailscale.com/admin/dns"
  say ""
  say "Or switch to a Cloudflare quick tunnel, which needs no certificate of"
  say "your own and nothing of yours reaches public certificate logs. The URL"
  say "changes each restart, so the Slack app has to be re-pointed if you"
  say "restart it mid-test."
  if confirm "Use a Cloudflare quick tunnel instead?"; then
    if ! command -v cloudflared >/dev/null 2>&1; then
      warn "cloudflared isn't installed. Install it, then re-run this script:"
      note "    brew install cloudflared"
      exit 1
    fi
    "$TS_CLI" funnel --https=443 off >/dev/null 2>&1 || true
    say "Starting the tunnel…"
    if ! start_cloudflared "$LOCAL_PORT"; then
      warn "cloudflared didn't produce a URL. Its output:"
      sed 's/^/    /' "$WORK/cloudflared.log" | tail -10
      exit 1
    fi
    PUBLIC_URL="$CF_URL"
    printf '  %s✓%s tunnel serving %s → localhost:%s\n' \
      "$GREEN" "$RESET" "$PUBLIC_URL" "$LOCAL_PORT"
    note "It runs in the background (pid $(cat "$WORK/cloudflared.pid"))."
    note "Stop it with: kill \$(cat $WORK/cloudflared.pid)"
  else
    say "Stopping — hawk-mod needs a working public HTTPS URL."
    exit 1
  fi
fi
write_env PUBLIC_URL "$PUBLIC_URL"

# ──────────────────────────────────────────────────────────────────────────
stage "Slack — the app"
say "The manifest goes on WITHOUT event subscriptions first."
note "Slack verifies the events URL the moment you save it, and the container"
note "can't answer that challenge until it has this app's signing secret."
note "Chicken-and-egg — so events get switched on in stage 10 instead."
say ""
sed -e "s#https://hawk-mod.example.org#${PUBLIC_URL}#g" \
    -e '/^settings:/,$d' docs/slack-app-manifest.yaml > "$WORK/manifest-step1.yaml"
printf 'settings:\n  org_deploy_enabled: false\n  socket_mode_enabled: false\n  token_rotation_enabled: false\n' \
  >> "$WORK/manifest-step1.yaml"
clip "$WORK/manifest-step1.yaml"
open_url "https://api.slack.com/apps"
if confirm "Do you already have a Slack app you want to use for hawk-mod?"; then
  warn "Pasting this manifest REPLACES that app's entire configuration —"
  warn "its scopes, redirect URLs, slash commands, the lot."
  say "Only do this to an app that is meant to be hawk-mod. If it's a working"
  say "integration doing something else, answer no next time and make a new one."
  if confirm "Replace that app's configuration?"; then
    step "Open the app → 'App Manifest' in the sidebar."
    step "Select YAML, replace the contents with your clipboard, Save Changes."
    step "If it warns that scopes changed, accept — you'll reinstall in stage 11."
  else
    say "Stopping. Nothing has been changed in Slack."
    exit 0
  fi
else
  step "Click 'Create New App' → 'From a manifest'."
  step "Pick the workspace you're testing in."
  step "Choose YAML, replace the contents with your clipboard, Next → Create."
fi
pause "Press Enter once the app is saved."

# ──────────────────────────────────────────────────────────────────────────
stage "Slack — credentials"
say "From the app's Basic Information page, under 'App Credentials'."
open_url "https://api.slack.com/apps"
step "Open your app → Basic Information → App Credentials."
ask SLACK_CLIENT_ID "Client ID:"
step "Click 'Show' on Client Secret, then copy it."
ask_secret SLACK_CLIENT_SECRET "Client Secret (hidden):"
step "Click 'Show' on Signing Secret, then copy it."
ask_secret SLACK_SIGNING_SECRET "Signing Secret (hidden):"
write_env SLACK_CLIENT_ID "$SLACK_CLIENT_ID"
write_env SLACK_CLIENT_SECRET "$SLACK_CLIENT_SECRET"
write_env SLACK_SIGNING_SECRET "$SLACK_SIGNING_SECRET"
say ""
say "The two secrets hawk-mod makes for itself:"
if [[ -n "$(_existing SLACK_STATE_SECRET || true)" ]]; then
  note "SLACK_STATE_SECRET already set — keeping it."
else
  write_env SLACK_STATE_SECRET "$(openssl rand -hex 32)"
fi
# Rotating this orphans every token already in the database: they are sealed
# with the old key and cannot be opened with a new one. A re-run must never
# silently do that.
if [[ -n "$(_existing TOKEN_ENCRYPTION_KEY || true)" ]]; then
  note "TOKEN_ENCRYPTION_KEY already set — keeping it."
  note "Replacing it would make every stored token undecryptable."
else
  write_env TOKEN_ENCRYPTION_KEY "$(openssl rand -base64 32)"
fi
note "TOKEN_ENCRYPTION_KEY encrypts adults' tokens at rest. On the real"
note "deployment, keep a copy — losing it means everyone re-authorises."
say ""
say "Message text: 'full' stores the text of monitored DMs; 'metadata' stores"
say "who/when/how-many and no text at all. Every policy violation is detected"
say "either way — content only matters when investigating one."
if confirm "Store message text during this test? (no = metadata only)"; then
  write_env LOG_MODE "full"
else
  write_env LOG_MODE "metadata"
fi
write_env TZ "America/New_York"

# ──────────────────────────────────────────────────────────────────────────
stage "Slack — findings channel"
say "Findings are posted to one private channel. It names students, so on the"
say "real workspace it is screened adults only."
step "In your test workspace, create a PRIVATE channel: #youth-protection"
step "Open it → click the channel name → scroll to the bottom of the About tab."
step "Copy the Channel ID (starts with C)."
ask ALERT_CHANNEL_ID "Channel ID:"
write_env ALERT_CHANNEL_ID "$ALERT_CHANNEL_ID"

# ──────────────────────────────────────────────────────────────────────────
stage "Google — a key that can only read test data"
say "hawk-mod reads the sheet as a Google service account. Make one of your"
say "own for this test, in a Google Cloud project of your own."
say ""
warn "Not the production service account (hawk-mod-lifecycle)."
say "Its key reads the real lifecycle sheet. A key made for this test is"
say "shared on your test sheet and nothing else, so this laptop never holds"
say "anything that can read a real student's record."
say ""
KEY_B64="$(_existing GOOGLE_SERVICE_ACCOUNT_KEY_BASE64 || true)"
if [[ -n "$KEY_B64" ]] && [[ -n "$(key_email "$KEY_B64")" ]] \
  && confirm "Keep the key already in .env ($(key_email "$KEY_B64"))?"; then
  SA_EMAIL="$(key_email "$KEY_B64")"
else
  say "Follow Part 1, steps 1–4, of docs/google-setup.md: a project, the Sheets"
  say "API switched on, a service account with no roles, and a JSON key for it."
  note "A project under your personal Google account is fine. A school or work"
  note "organization may block key creation; that doc says what to do."
  open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
  pause "Press Enter once the JSON key has downloaded."
  ask KEY_FILE "Path to the downloaded key file:"
  KEY_FILE="${KEY_FILE/#\~/$HOME}"
  if [[ ! -r "$KEY_FILE" ]]; then
    warn "Can't read $KEY_FILE. Re-run with the right path."
    exit 1
  fi
  KEY_B64="$(base64 < "$KEY_FILE" | tr -d '\n')"
  SA_EMAIL="$(key_email "$KEY_B64")"
  if [[ -z "$SA_EMAIL" ]]; then
    warn "That file isn't a service account key (no client_email in it)."
    exit 1
  fi
  write_env GOOGLE_SERVICE_ACCOUNT_KEY_BASE64 "$KEY_B64"
  note "It is in .env now, which git ignores. Delete the downloaded file:"
  note "    rm \"$KEY_FILE\""
fi
say ""
say "The service account is ${BOLD}${SA_EMAIL}${RESET}"
note "You'll share the test sheet with it in the next stage."

# ──────────────────────────────────────────────────────────────────────────
stage "Google — the test lifecycle sheet"
say "A sheet with the tabs and columns hawk-mod reads, and two fake people:"
say "a mentor (you) and a student (your second account). Nothing else."
say ""
say "hawk-mod matches a sheet row to a Slack account by email, so give it the"
say "addresses the two Slack accounts sign in with."
ask MENTOR_EMAIL "Your Slack account's email (the mentor):"
ask STUDENT_EMAIL "The student account's email:"
MENTOR_EMAIL="$(printf '%s' "$MENTOR_EMAIL" | tr '[:upper:]' '[:lower:]')"
STUDENT_EMAIL="$(printf '%s' "$STUDENT_EMAIL" | tr '[:upper:]' '[:lower:]')"
if [[ -z "$MENTOR_EMAIL" || -z "$STUDENT_EMAIL" || "$MENTOR_EMAIL" == "$STUDENT_EMAIL" ]]; then
  warn "Those need to be two different addresses. Re-run with both."
  exit 1
fi
say ""
say "Parental consent for the student is the sheet's Slack Consent Expiry."
say "Leave it blank and you'll get an unconsented_account finding — which is"
say "correct, and worth seeing once. You can fill it in on the sheet later."
# Placeholder dates for fake people. Real ones are copied from FIRST and the
# state and never computed; these only have to be dates the screening rules
# accept as current: annual items end on the next 1 August, and the
# three-year ones sit two years out, inside their bound.
read -r NEXT_AUG1 IN_TWO_YEARS < <(python3 -c '
import datetime as d
t = d.date.today()
aug1 = d.date(t.year if (t.month, t.day) < (8, 1) else t.year + 1, 8, 1)
print(aug1.isoformat(), (t + d.timedelta(days=730)).isoformat())
')
if confirm "Record consent for the test student?"; then
  STUDENT_CONSENT="$NEXT_AUG1"
else
  STUDENT_CONSENT=""
fi
write_test_sheet
printf '  %s✓%s %s tabs ready in %s\n' "$GREEN" "$RESET" "${#SHEET_TAB_LIST[@]}" "$WORK/test-sheet"
say ""
step "Make a new, blank Google Sheet, signed in as yourself."
step "Name it something obvious, e.g. \"hawk-mod test lifecycle sheet\"."
open_url "https://sheets.new"
pause "Press Enter once it's open."
first=1
for tab in "${SHEET_TAB_LIST[@]}"; do
  say ""
  say "Tab ${BOLD}${tab}${RESET}:"
  clip "$WORK/test-sheet/${tab}.tsv"
  if (( first )); then
    step "Double-click the tab at the bottom (Sheet1) and rename it: ${tab}"
    first=0
  else
    step "Add a tab (+ at the bottom left) and name it exactly: ${tab}"
  fi
  step "Click cell A1 and paste."
  pause "Press Enter once it's pasted."
done
say ""
note "Names must match exactly, capitals and underscores included — hawk-mod"
note "refuses a sheet with a tab or column it can't find, rather than guess."
say ""
step "Share → add ${SA_EMAIL} as Editor, untick \"Notify people\"."
note "Editor, not Viewer: once the roster is built, hawk-mod writes each"
note "person's Slack User ID back to the sheet."
pause "Press Enter once it's shared."
say ""
say "The sheet's ID is the long part of its URL, between /d/ and /edit."
ask LIFECYCLE_SHEET_ID "Sheet URL or ID:"
LIFECYCLE_SHEET_ID="$(printf '%s' "$LIFECYCLE_SHEET_ID" \
  | sed -E 's|^.*/spreadsheets/d/([^/?#]+).*$|\1|')"
write_env LIFECYCLE_SHEET_ID "$LIFECYCLE_SHEET_ID"
note "It lives in .env and nowhere else. The repo is public: never paste a"
note "sheet ID into anything committed."

# ──────────────────────────────────────────────────────────────────────────
stage "Start the container"
say "Starting hawk-mod with the values collected so far."
"${COMPOSE[@]}" up -d --build >/dev/null
say "Waiting for the health check…"
for _ in $(seq 1 30); do
  [[ "$(docker inspect --format '{{.State.Health.Status}}' hawk-mod 2>/dev/null)" == "healthy" ]] && break
  sleep 2
done
if [[ "$(docker inspect --format '{{.State.Health.Status}}' hawk-mod 2>/dev/null)" != "healthy" ]]; then
  warn "Container isn't healthy. Logs:"
  "${COMPOSE[@]}" logs --tail=30 | sed 's/^/    /'
  exit 1
fi
printf '  %s✓%s container healthy\n' "$GREEN" "$RESET"
say "Checking Slack can reach it through the Funnel…"
if curl -fsS --max-time 15 "${PUBLIC_URL}/health" >"$WORK/health.json" 2>&1; then
  printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$(cat "$WORK/health.json")"
else
  warn "Couldn't reach ${PUBLIC_URL}/health from the public internet."
  step "Check '$TS_CLI funnel status'. Slack cannot work until this responds."
  exit 1
fi
say ""
say "Checking it can read the test sheet (this changes nothing)…"
if hm lifecycle plan >"$WORK/plan.txt" 2>&1; then
  sed 's/^/    /' "$WORK/plan.txt" | head -12
  PEOPLE_ON_SHEET="$(sed -nE 's/^People: ([0-9]+).*/\1/p' "$WORK/plan.txt")"
  # The test sheet has two people. A sheet with a team's worth is almost
  # certainly the real one, and nothing after this point should read it.
  if (( ${PEOPLE_ON_SHEET:-0} > 10 )); then
    warn "That sheet has ${PEOPLE_ON_SHEET} people on it. The test sheet has two."
    if ! confirm "Is this really a test sheet of your own?"; then
      say "Stopping. Point LIFECYCLE_SHEET_ID in .env at the test sheet and re-run."
      "${COMPOSE[@]}" down >/dev/null 2>&1 || true
      exit 1
    fi
  fi
else
  warn "hawk-mod couldn't read the sheet:"
  sed 's/^/    /' "$WORK/plan.txt" | tail -8
  say ""
  note "  403 / permission      → share it with ${SA_EMAIL:-the service account} (stage 8)"
  note "  Sheets API disabled   → enable it in that Cloud project"
  note "  no tab / no column    → rename it to match exactly, then re-run"
  exit 1
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Slack — switch on events"
say "Now that the container is live and holds the signing secret, apply the"
say "full manifest. Slack will verify the events URL against it."
sed "s#https://hawk-mod.example.org#${PUBLIC_URL}#g" \
  docs/slack-app-manifest.yaml > "$WORK/manifest-step2.yaml"
clip "$WORK/manifest-step2.yaml"
open_url "https://api.slack.com/apps"
step "Open your app → 'App Manifest' in the sidebar."
step "Replace the whole manifest with your clipboard, then Save Changes."
step "It should say the request URL was verified. If not, check the logs with:"
note "    ${COMPOSE[*]} logs -f"
pause "Press Enter once the manifest saved cleanly."

# ──────────────────────────────────────────────────────────────────────────
stage "Install and enrol yourself"
say "Installing puts the bot in the workspace and enrols you as the first"
say "monitored adult — the same URL does both."
open_url "${PUBLIC_URL}/slack/install"
step "Click through the authorisation screen. Read the scopes it asks for:"
note "    im:history / mpim:history — this is the DM visibility, on your account."
step "You should land on a page confirming you're enrolled."
pause "Press Enter once you see it."
step "In Slack, open #youth-protection and invite the bot: /invite @hawk-mod"
pause "Press Enter once the bot is in the channel."
curl -fsS "${PUBLIC_URL}/health" 2>/dev/null | sed 's/^/  /' || true

# ──────────────────────────────────────────────────────────────────────────
stage "Build the roster from the sheet"
say "The roster — who hawk-mod treats as a student and who as an adult — comes"
say "only from the lifecycle sheet. First the dry run, which changes nothing:"
say ""
note "The student account has to be in the workspace for its row to link to"
note "it. If it isn't yet, invite it and accept now (a private browser window"
note "is the easy way to hold both sessions); the hourly run links it later"
note "otherwise."
pause "Press Enter when you're ready for the dry run."
say ""
if ! hm lifecycle roster 2>&1 | sed 's/^/    /'; then
  warn "The dry run failed — check the logs."
  exit 1
fi
say ""
note "Reading it: P0101 should be created as an adult and P0102 as a student,"
note "each with a Slack account. A person with no Slack account means their"
note "email on the sheet isn't the one that Slack account signs in with; type"
note "their Slack User ID into the sheet instead (profile → ⋯ → Copy member ID)."
note "\"Refused\" on a first apply usually means an older roster in this"
note "volume; start clean with: ${COMPOSE[*]} down -v"
say ""
if confirm "Apply it?"; then
  hm lifecycle roster --apply 2>&1 | tail -3 | sed 's/^/    /' \
    || warn "apply failed — check the logs"
else
  say "Skipped. Apply later from Slack: /hawkmod lifecycle roster apply"
fi
say ""
say "The roster now:"
"${COMPOSE[@]}" exec -T hawk-mod node --input-type=module -e '
const { listPeople } = await import("./dist/src/db/repo.js");
for (const p of listPeople()) console.log(`  ${p.role.padEnd(18)} ${p.full_name}`);
' 2>/dev/null || note "  (could not list — check the logs)"
say ""
note "From here the sheet is the only way in: an hourly run (:20 past) applies"
note "what it says. After editing the sheet, /hawkmod sync applies it now."
note "Nothing to grant yourself either: /hawkmod answers to Slack's Workspace"
note "Owners and Admins, read live. You installed the app, so you can run it."

# ──────────────────────────────────────────────────────────────────────────
stage "Prove it works"
say "The actual test: a 1:1 DM between an adult and a student is prohibited"
say "outright, so hawk-mod should flag it the moment it happens."
step "From YOUR account, send the student account a direct message."
pause "Press Enter once you've sent it."
say ""
say "Findings on record:"
"${COMPOSE[@]}" exec -T hawk-mod node dist/src/cli/index.js findings | sed 's/^/  /' || true
say ""
step "Check #youth-protection — the alert should be there too."
say ""
note "Nothing yet? Both accounts have to be on the roster from the sheet, so"
note "check  /hawkmod whois @them   — does it say student?"
note "If not, fix their row on the test sheet and run  /hawkmod sync"
note "then force a re-read of DM history:"
note "    ${COMPOSE[*]} exec hawk-mod node dist/src/cli/index.js backfill"
say ""
say "Worth trying while you're here, to see the boundaries hold:"
step "DM another adult — nothing should be recorded."
step "Have the student DM a second student — also nothing."
note "Only conversations with both an adult and a student are logged."

finish
say "Useful from here:"
note "  logs:        ${COMPOSE[*]} logs -f"
note "  findings:    ${COMPOSE[*]} exec hawk-mod node dist/src/cli/index.js findings"
note "  in Slack:    /hawkmod status"
note "  sheet edits: /hawkmod sync   (or wait for the hourly run)"
note "  stop:        ${COMPOSE[*]} down"
if [[ -f "$WORK/cloudflared.pid" ]]; then
  note "  close the public tunnel: kill \$(cat $WORK/cloudflared.pid)"
else
  note "  close the public tunnel: $TS_CLI funnel --https=443 off"
fi
say ""
warn "Wipe the test data before reusing this machine for anything real:"
note "  ${COMPOSE[*]} down -v"
note "When you're done testing, delete the test service account's key in the"
note "Cloud console too, not only the copy in .env."
printf '\n'
